import { AuthOtp } from "@/components/design-for-ai/auth-otp";

<AuthOtp
  channel="email"
  destination={user.email}
  onVerify={async (code) => {
    const res = await fetch("/api/verify", { method: "POST", body: JSON.stringify({ code }) });
    if (res.status === 410) return { ok: false, reason: "expired" };
    if (res.status === 429) return { ok: false, reason: "locked" };
    if (!res.ok) return { ok: false, reason: "invalid", attemptsLeft: Number(res.headers.get("X-Attempts-Left")) };
    return { ok: true };
  }}
  onResend={() => fetch("/api/verify/resend", { method: "POST" }).then(() => undefined)}
  onChangeDestination={(email) => sendCode(email)}
  onVerified={() => router.push("/app")}
/>

import { AuthSsoDetect } from "@/components/design-for-ai/auth-sso-detect";

<AuthSsoDetect
  brand="Acme"
  title="Sign in to Acme"
  detect={async (domain) => {
    const res = await fetch(`/api/sso/lookup?domain=${domain}`);
    return res.json(); // SsoWorkspace[]: [] means password sign-in
  }}
  onSsoContinue={async (workspace, email) => {
    window.location.assign(`/api/sso/start?ws=${workspace.id}&login_hint=${encodeURIComponent(email)}`);
  }}
  onPasswordSignIn={async (email, password) => {
    const res = await fetch("/api/login", { method: "POST", body: JSON.stringify({ email, password }) });
    if (!res.ok) throw new Error("That password doesn’t match.");
  }}
/>

